  // The sqrt() ease-out makes the color change fast at first, then slow down.
  finalColor.set(mix(navy, brightOrange, value));

  finalColor.end();
}

function drawShape() {
  let t = millis() * 0.001;
  let sinVal = 0.5 + 0.5 * sin(t);
  let size = 10 + sqrt(sinVal) * 30;
